264	The following theorem records the self-testing (rigidity) properties of the Magic Square game. It is used in the soundness analysis of the Pauli basis test to enforce anticommutation relations between certain pairs of observables.
265	With zero-based labels, the paper's variables $1$ and $5$ have labels $0$ and
266	$4$, respectively.
267	
268	\begin{theorem}[Rigidity of the Magic Square game]\label{thm:ms-rigidity}
269		\lean{MIPStarRE.QPBT.exists_ms_rigidity}
270		\leanok
271		\uses{def:ms-game, def:tensor-product-value, def:EPR, def:povm-distance}
272		Let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy that succeeds in the Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ with probability $1-\eps$, where $\ket{\psi} \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$. Then there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\hilb_{\mathrm A'}, \hilb_{\mathrm B'} \cong (\C^2)^{\ot 2}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''}$ are finite dimensional, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A''} \ot \hilb_{\mathrm B''}$, such that:
273		\begin{enumerate}
274			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket{\psi} - \ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}} \bigr\| \le O(\sqrt\eps)$;
275			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$,
276			\begin{align*}
277				\tilde A^{\mathsf{Variable}_1}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^X_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
278				\tilde A^{\mathsf{Variable}_5}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^Z_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
279				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^X_b)_{\mathrm B'}\;,\\
280				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^Z_b)_{\mathrm B'}\;,
281			\end{align*}
282			where each $\approx_{\sqrt\eps}$ holds with respect to the state $\ket{\mathrm{EPR}_2}^{\ot 2}_{\mathrm{A'B'}} \ot \ket{\mathrm{aux}}_{\mathrm{A''B''}}$ and the answer summation is over $b \in \{0,1\}$, and the approximation bounds carry implicit universal constants.
283		\end{enumerate}
284		As a consequence, letting $\tilde A^{\mathsf{Variable}_1} = \tilde A^{\mathsf{Variable}_1}_0 - \tilde A^{\mathsf{Variable}_1}_1$ and $\tilde A^{\mathsf{Variable}_5} = \tilde A^{\mathsf{Variable}_5}_0 - \tilde A^{\mathsf{Variable}_5}_1$ denote the associated observables, it holds that
285		\begin{align*}
286			\tilde A^{\mathsf{Variable}_1} \tilde A^{\mathsf{Variable}_5} \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} -\, \tilde A^{\mathsf{Variable}_5} \tilde A^{\mathsf{Variable}_1} \ot I_{\mathrm{B'B''}}\;,\\
287			I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1} \tilde B^{\mathsf{Variable}_5} &\approx_{\sqrt\eps} -\, I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5} \tilde B^{\mathsf{Variable}_1}\;,
288		\end{align*}
289		where, for operators $M$, $N$ that are not POVM elements, the notation $M \approx_\delta N$ means $\bra{\psi} (M-N)^\dagger (M-N) \ket{\psi} \le O(\delta)$ with respect to the same state.
290	\end{theorem}
291	\begin{proof}
292		This result is imported from Theorem~6.9 of~\cite{Coladangelo2017Robust}. There are two minor differences between their statement and the one given here. First, they state a robustness of $O(\eps)$, but measure the closeness of the actual and ideal states in trace norm; expressed as the Euclidean distance between $\phi_{\mathrm A} \ot \phi_{\mathrm B}\ket{\psi}$ and $\ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}}$, this becomes $O(\sqrt\eps)$. Second, their ideal observables for the $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ questions are $I \ot \sigma^Z$ and $\sigma^Z\sigma^X \ot \sigma^Z\sigma^X$; under a local change of basis these are equivalent to $\sigma^X \ot I$ and $\sigma^Z \ot I$, respectively.
293	\end{proof}
